using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        [Fact]
        public void Constructor_ValidInputs_SetsPropertiesCorrectly()
        {
            // Arrange
            var items = new List<string> { "a", "b", "c" };

            // Act
            var result = new PaginatedList<string>(items, 10, 2, 3);

            // Assert
            Assert.Equal(2, result.PageIndex);
            Assert.Equal(4, result.TotalPages); // ceil(10/3) = 4
            Assert.Equal(3, result.Count);
            Assert.Contains("a", result);
            Assert.Contains("b", result);
            Assert.Contains("c", result);
        }

        [Theory]
        [InlineData(10, 3, 4)]   // ceil(10/3) = 4
        [InlineData(9, 3, 3)]    // ceil(9/3) = 3
        [InlineData(1, 10, 1)]   // ceil(1/10) = 1
        [InlineData(0, 10, 0)]   // ceil(0/10) = 0
        [InlineData(11, 5, 3)]   // ceil(11/5) = 3
        public void Constructor_DifferentCounts_CalculatesTotalPagesCorrectly(int count, int pageSize, int expectedTotalPages)
        {
            // Arrange
            var items = new List<int>();

            // Act
            var result = new PaginatedList<int>(items, count, 1, pageSize);

            // Assert
            Assert.Equal(expectedTotalPages, result.TotalPages);
        }

        [Fact]
        public void HasPreviousPage_OnFirstPage_ReturnsFalse()
        {
            // Arrange
            var list = new PaginatedList<int>(new List<int>(), 10, 1, 5);

            // Act & Assert
            Assert.False(list.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_OnSecondPage_ReturnsTrue()
        {
            // Arrange
            var list = new PaginatedList<int>(new List<int>(), 10, 2, 5);

            // Act & Assert
            Assert.True(list.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_OnLastPage_ReturnsFalse()
        {
            // Arrange
            var list = new PaginatedList<int>(new List<int>(), 10, 2, 5); // 2 pages total, on page 2

            // Act & Assert
            Assert.False(list.HasNextPage);
        }

        [Fact]
        public void HasNextPage_OnFirstPageWithMorePages_ReturnsTrue()
        {
            // Arrange
            var list = new PaginatedList<int>(new List<int>(), 10, 1, 5); // 2 pages total, on page 1

            // Act & Assert
            Assert.True(list.HasNextPage);
        }

        [Fact]
        public void Create_ReturnsCorrectPageOfItems()
        {
            // Arrange
            var source = Enumerable.Range(1, 20).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 2, 5);

            // Assert
            Assert.Equal(2, result.PageIndex);
            Assert.Equal(4, result.TotalPages);
            Assert.Equal(5, result.Count);
            Assert.Equal(6, result[0]);  // items 6-10 on page 2
            Assert.Equal(10, result[4]);
        }

        [Fact]
        public void Create_FirstPage_ReturnsFirstItems()
        {
            // Arrange
            var source = Enumerable.Range(1, 15).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, 5);

            // Assert
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(3, result.TotalPages);
            Assert.Equal(1, result[0]);
            Assert.Equal(5, result[4]);
        }

        [Fact]
        public void Create_LastPagePartial_ReturnsRemainingItems()
        {
            // Arrange
            var source = Enumerable.Range(1, 7).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 2, 5);

            // Assert
            Assert.Equal(2, result.PageIndex);
            Assert.Equal(2, result.TotalPages);
            Assert.Equal(2, result.Count); // only 2 items on last page
            Assert.Equal(6, result[0]);
            Assert.Equal(7, result[1]);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            // Arrange
            var source = Enumerable.Empty<int>().AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, 5);

            // Assert
            Assert.Empty(result);
            Assert.Equal(0, result.TotalPages);
            Assert.Equal(1, result.PageIndex);
        }
    }
}

using System;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _sut;

        public NotificationServiceTests()
        {
            _sut = new NotificationService();
            // Drain any existing notifications from prior tests (static queue)
            while (_sut.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            _sut.Dispose();
        }

        [Fact]
        public void SendNotification_WithDisplayName_CreatesNotificationWithCorrectMessage()
        {
            // Arrange & Act
            _sut.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("New Student 'John Doe' has been created", notification.Message);
            Assert.Equal("Admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesEntityIdInMessage()
        {
            // Arrange & Act
            _sut.SendNotification("Course", "42", null, EntityOperation.UPDATE, "Teacher");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Course (ID: 42) has been updated", notification.Message);
        }

        [Fact]
        public void SendNotification_WithoutUserName_DefaultsToSystem()
        {
            // Arrange & Act
            _sut.SendNotification("Department", "5", "Math", EntityOperation.DELETE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_DeleteOperation_GeneratesDeleteMessage()
        {
            // Arrange & Act
            _sut.SendNotification("Instructor", "3", "Jane Smith", EntityOperation.DELETE, "Admin");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Instructor 'Jane Smith' has been deleted", notification.Message);
            Assert.Equal("DELETE", notification.Operation);
        }

        [Fact]
        public void SendNotification_UpdateOperation_GeneratesUpdateMessage()
        {
            // Arrange & Act
            _sut.SendNotification("Student", "10", "Bob", EntityOperation.UPDATE, "System");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.Equal("Student 'Bob' has been updated", notification.Message);
        }

        [Fact]
        public void SendNotification_OverloadWithoutDisplayName_Works()
        {
            // Arrange & Act
            _sut.SendNotification("Student", "1", EntityOperation.CREATE, "Admin");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student (ID: 1) has been created", notification.Message);
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            // Act
            var result = _sut.ReceiveNotification();

            // Assert
            Assert.Null(result);
        }

        [Fact]
        public void ReceiveNotification_MultipleNotifications_ReturnsFIFO()
        {
            // Arrange
            _sut.SendNotification("A", "1", "First", EntityOperation.CREATE, "User");
            _sut.SendNotification("B", "2", "Second", EntityOperation.UPDATE, "User");
            _sut.SendNotification("C", "3", "Third", EntityOperation.DELETE, "User");

            // Act & Assert
            var first = _sut.ReceiveNotification();
            Assert.Equal("A", first.EntityType);

            var second = _sut.ReceiveNotification();
            Assert.Equal("B", second.EntityType);

            var third = _sut.ReceiveNotification();
            Assert.Equal("C", third.EntityType);

            var empty = _sut.ReceiveNotification();
            Assert.Null(empty);
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToCurrentTime()
        {
            // Arrange
            var before = DateTime.Now.AddSeconds(-1);

            // Act
            _sut.SendNotification("Test", "1", "Item", EntityOperation.CREATE, "User");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.True(notification.CreatedAt >= before);
            Assert.True(notification.CreatedAt <= DateTime.Now.AddSeconds(1));
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // Act & Assert (no-op implementation, should not throw)
            var exception = Record.Exception(() => _sut.MarkAsRead(1));
            Assert.Null(exception);
        }

        [Fact]
        public void SendNotification_EmptyDisplayName_UsesIdFallback()
        {
            // Arrange & Act
            _sut.SendNotification("Entity", "99", "", EntityOperation.CREATE, "User");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.Equal("Entity (ID: 99) has been created", notification.Message);
        }

        [Fact]
        public void SendNotification_WhitespaceDisplayName_UsesIdFallback()
        {
            // Arrange & Act
            _sut.SendNotification("Entity", "99", "   ", EntityOperation.CREATE, "User");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.Equal("Entity (ID: 99) has been created", notification.Message);
        }

        [Fact]
        public void Dispose_CanBeCalledMultipleTimes()
        {
            // Act & Assert
            var service = new NotificationService();
            var exception = Record.Exception(() =>
            {
                service.Dispose();
                service.Dispose();
            });
            Assert.Null(exception);
        }
    }
}

