using System;
using System.Linq;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class SchoolContextTests : IDisposable
    {
        private readonly SchoolContext _context;

        public SchoolContextTests()
        {
            _context = TestDbContextFactory.Create();
        }

        public void Dispose()
        {
            _context.Dispose();
        }

        [Fact]
        public void Context_CanCreateDatabase()
        {
            // Assert
            Assert.NotNull(_context);
            Assert.True(_context.Database.IsInMemory());
        }

        [Fact]
        public void Context_StudentsDbSet_IsAccessible()
        {
            // Assert
            Assert.NotNull(_context.Students);
        }

        [Fact]
        public void Context_CoursesDbSet_IsAccessible()
        {
            // Assert
            Assert.NotNull(_context.Courses);
        }

        [Fact]
        public void Context_DepartmentsDbSet_IsAccessible()
        {
            // Assert
            Assert.NotNull(_context.Departments);
        }

        [Fact]
        public void Context_InstructorsDbSet_IsAccessible()
        {
            // Assert
            Assert.NotNull(_context.Instructors);
        }

        [Fact]
        public void Context_EnrollmentsDbSet_IsAccessible()
        {
            // Assert
            Assert.NotNull(_context.Enrollments);
        }

        [Fact]
        public void Context_CanAddAndRetrieveStudent()
        {
            // Arrange
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "User",
                EnrollmentDate = DateTime.Parse("2023-01-01")
            };

            // Act
            _context.Students.Add(student);
            _context.SaveChanges();

            // Assert
            var retrieved = _context.Students.First(s => s.LastName == "User");
            Assert.Equal("Test", retrieved.FirstMidName);
            Assert.Equal(DateTime.Parse("2023-01-01"), retrieved.EnrollmentDate);
        }

        [Fact]
        public void Context_CanAddAndRetrieveCourse()
        {
            // Arrange
            var course = new Course
            {
                CourseID = 5001,
                Title = "Test Course",
                Credits = 4,
                DepartmentID = 0
            };

            // Act
            _context.Courses.Add(course);
            _context.SaveChanges();

            // Assert
            var retrieved = _context.Courses.Find(5001);
            Assert.NotNull(retrieved);
            Assert.Equal("Test Course", retrieved.Title);
            Assert.Equal(4, retrieved.Credits);
        }

        [Fact]
        public void Context_CanAddAndRetrieveDepartment()
        {
            // Arrange
            var dept = new Department
            {
                Name = "Physics",
                Budget = 250000,
                StartDate = DateTime.Parse("2020-01-01")
            };

            // Act
            _context.Departments.Add(dept);
            _context.SaveChanges();

            // Assert
            var retrieved = _context.Departments.First(d => d.Name == "Physics");
            Assert.Equal(250000, retrieved.Budget);
        }

        [Fact]
        public void Context_CanAddAndRetrieveInstructor()
        {
            // Arrange
            var instructor = new Instructor
            {
                FirstMidName = "Jane",
                LastName = "Smith",
                HireDate = DateTime.Parse("2015-06-15")
            };

            // Act
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            // Assert
            var retrieved = _context.Instructors.First(i => i.LastName == "Smith");
            Assert.Equal("Jane", retrieved.FirstMidName);
        }

        [Fact]
        public void Context_CanAddEnrollmentWithRelationships()
        {
            // Arrange
            var student = new Student { FirstMidName = "A", LastName = "B", EnrollmentDate = DateTime.Now };
            _context.Students.Add(student);
            var course = new Course { CourseID = 9001, Title = "X", Credits = 3, DepartmentID = 0 };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var enrollment = new Enrollment
            {
                StudentID = student.ID,
                CourseID = course.CourseID,
                Grade = Grade.A
            };

            // Act
            _context.Enrollments.Add(enrollment);
            _context.SaveChanges();

            // Assert
            var retrieved = _context.Enrollments.First(e => e.StudentID == student.ID && e.CourseID == course.CourseID);
            Assert.Equal(Grade.A, retrieved.Grade);
        }

        [Fact]
        public void Context_CourseAssignment_CompositeKey_Works()
        {
            // Arrange
            var instructor = new Instructor { FirstMidName = "X", LastName = "Y", HireDate = DateTime.Now };
            _context.Instructors.Add(instructor);
            var course = new Course { CourseID = 8001, Title = "Z", Credits = 2, DepartmentID = 0 };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var assignment = new CourseAssignment
            {
                InstructorID = instructor.ID,
                CourseID = course.CourseID
            };

            // Act
            _context.CourseAssignments.Add(assignment);
            _context.SaveChanges();

            // Assert
            var retrieved = _context.CourseAssignments.Find(course.CourseID, instructor.ID);
            Assert.NotNull(retrieved);
        }

        [Fact]
        public void Context_NotificationsDbSet_IsAccessible()
        {
            // Assert
            Assert.NotNull(_context.Notifications);
        }

        [Fact]
        public void Context_CanAddNotification()
        {
            // Arrange
            var notification = new Notification
            {
                EntityType = "Student",
                EntityId = "1",
                Operation = "CREATE",
                Message = "Test notification",
                CreatedAt = DateTime.Now,
                CreatedBy = "System",
                IsRead = false
            };

            // Act
            _context.Notifications.Add(notification);
            _context.SaveChanges();

            // Assert
            var retrieved = _context.Notifications.First();
            Assert.Equal("Test notification", retrieved.Message);
            Assert.Equal("Student", retrieved.EntityType);
        }
    }
}

